			increment(expectedCounts, key(2, out + 1, quad.predicate()));
			increment(expectedCounts, key(3, out, quad.predicate(), quad.subject()));
			increment(expectedCounts, key(3, out + 1, quad.predicate(), quad.object()));
			increment(expectedCounts, key(4, out, quad.subject(), quad.predicate()));
